/**
 * activateNavLinkManually:
 *   Fallback tanpa Bootstrap: aktifkan nav-link + tab-pane secara manual,
 *   agar perpindahan tab TIDAK pernah gagal senyap.
 */
function activateNavLinkManually(link) {

    // Non-aktifkan semua nav-link & tab-pane di halaman yang sama
    document
        .querySelectorAll('ul.nav-tabs a.nav-link')
        .forEach(function(item) {

            var pane = document.querySelector(item.getAttribute('href'));

            item.classList.remove('active');
            item.removeAttribute('aria-selected');

            if (pane) {
                pane.classList.remove('active', 'show');
            }

        });

    link.classList.add('active');
    link.setAttribute('aria-selected', 'true');

    var targetPane = document.querySelector(link.getAttribute('href'));

    if (targetPane) {
        targetPane.classList.add('active', 'show');
    } else {

        console.warn(
            '[schedule-settings] tab-pane tidak ditemukan untuk ' +
            link.getAttribute('href')
        );

    }

}

/**
 * showTabForMethod:
 *   Aktifkan tab metode yang sesuai dengan nama method.
 *   Tidak pernah gagal senyap: bila bootstrap tidak tersedia atau
 *   getOrCreateInstance melempar error, dipakai fallback manual.
 */
function showTabForMethod(method) {

    var selector = SCHEDULE_METHOD_TABS[method];

    if (!selector) {

        console.warn(
            '[schedule-settings] showTabForMethod: method tidak dikenal:',
            method
        );

        return false;

    }

    var link = document.querySelector(
        'ul.nav-tabs a[href="' + selector + '"]'
    );

    if (!link) {

        console.warn(
            '[schedule-settings] showTabForMethod: nav-link tidak ditemukan: ' +
            selector
        );

        return false;

    }

    if (typeof bootstrap === 'undefined' || !bootstrap.Tab) {

        console.warn(
            '[schedule-settings] bootstrap.Tab tidak tersedia, ' +
            'memakai fallback aktivasi manual untuk ' + selector
        );

        activateNavLinkManually(link);

        return true;

    }

    try {

        var tab = bootstrap.Tab.getOrCreateInstance(link);
        tab.show();

        return true;

    } catch (err) {

        console.warn(
            '[schedule-settings] bootstrap.Tab.show() gagal, ' +
            'memakai fallback manual: ' + err.message
        );

        activateNavLinkManually(link);

        return true;

    }

}

