/**
 * applyScheduleSettings:
 *   Pulihkan radio Metode Penyebaran Video, isi field method terkait,
 *   lalu pindahkan tab ke method tersebut.
 *   TIDAK pernah gagal senyap: setiap jalur gagal mengembalikan false dan
 *   mencatat console.warn berisi sebab + key file yang terbaca.
 */
function applyScheduleSettings(data) {

    var SUPPORTED_METHODS = ["interval", "fixed", "weekly", "pattern"];

    if (!data || typeof data !== "object") {

        console.warn(
            '[schedule-settings] applyScheduleSettings: data kosong/bukan object:',
            data
        );

        return false;

    }

    var method = data.method;

    if (!method || SUPPORTED_METHODS.indexOf(method) === -1) {

        console.warn(
            '[schedule-settings] applyScheduleSettings: method tidak dikenal:',
            method,
            '| top-level keys:',
            Object.keys(data),
            '| config keys:',
            Object.keys(data.config || {})
        );

        return false;

    }

    var appliers = {
        interval: typeof applyIntervalSettings === "function" ? applyIntervalSettings : null,
        fixed: typeof applyFixedSettings === "function" ? applyFixedSettings : null,
        weekly: typeof applyWeeklySettings === "function" ? applyWeeklySettings : null,
        pattern: typeof applyPatternSettings === "function" ? applyPatternSettings : null
    };

    if (!appliers[method]) {

        console.warn(
            '[schedule-settings] applyScheduleSettings: applier untuk method "' +
            method + '" belum ter-load. Tersedia:',
            Object.keys(appliers).filter(function(key) {
                return !!appliers[key];
            })
        );

        return false;

    }

    // Config wajib ada; kalau hilang, tetap lanjut dengan warning (tidak throw)
    if (!data.config || typeof data.config !== "object") {

        console.warn(
            '[schedule-settings] config kosong untuk method "' + method +
            '". top-level keys file:',
            Object.keys(data)
        );

    }

    // Pulihkan Metode Penyebaran Video
    if (data.distribution_method) {

        var radios = document.querySelectorAll(
            'input[name="distribution_method"]'
        );

        for (var i = 0; i < radios.length; i++) {

            radios[i].checked = (radios[i].value === data.distribution_method);

        }

        for (var j = 0; j < radios.length; j++) {

            if (radios[j].checked) {

                // Trigger handler perubahan state (bila ada) supaya
                // metode penyebaran benar-benar aktif.
                radios[j].dispatchEvent(
                    new Event("change", { bubbles: true })
                );

                break;

            }

        }

    }

    // Isi konfigurasi method (Upload Directory & Start Date sengaja tidak disentuh).
    // Config dikirim sebagai object baru (bukan copy) agar modifikasi applier
    // tidak merusak data aslinya; applier sendiri harus toleran bila config {}.
    appliers[method](data.config || {});

    // Pindah ke tab method yang dimuat
    showTabForMethod(method);

    return true;

}

