        interval: 'Interval',
        fixed: 'Fixed Time',
        weekly: 'Weekly',
        pattern: 'Pattern'
    };

    const topLevelKeys = Object.keys(jsonData || {});

    // 1. Fungsi load harus tersedia (lookup dinamis saat runtime klik)
    var applyFn = (typeof window.applyScheduleSettings === 'function')
        ? window.applyScheduleSettings
        : null;

