    } catch (err) {

        console.error('[schedule-settings] applyScheduleSettings throw:', err);

        alert(
            'Gagal memuat pengaturan (method: ' + method + '): ' + err.message
        );

        return;

    }

    if (applied) {

        alert(
            'Pengaturan berhasil dimuat. ' +
            'Tab otomatis berpindah ke: ' +
            (methodLabels[method] || method)
        );

