            "tidak ada / bukan object. config keys yang dibaca:",
            Object.keys(cfg)
        );

        schedule = {};

    }

    Object.keys(weeklySchedule).forEach(function(day) {

        var raw = schedule[day];

        var times = Array.isArray(raw)
            ? raw.map(function(value) {
                return (value === null || value === undefined) ? "" : String(value);
            }).filter(function(value) {
                return value !== "";
            })
            : [];

        if (!Array.isArray(raw) && raw !== undefined) {
            console.warn(
                "[schedule-settings] applyWeeklySettings: jadwal hari " + day +
                " bukan array, diabaikan:",
                raw
            );
        }

        times.sort();
        weeklySchedule[day] = times;
        renderWeekly(day);

    });

}

