# ---------------------------------------------------------------
# AC-7: Upload Directory & semua Start Date tetap kosong.
#       CATATAN: #import_start_date sengaja diberi default "besok"
#       oleh handler DOMContentLoaded milik tab Import (perilaku
#       pra-eksisting, BUKAN bagian dari fitur save/load ini) dan
#       tidak pernah disimpan ke file settings.
# ---------------------------------------------------------------
empties = page.evaluate('''() => {
    var ids = ['upload_directory', 'start_date', 'fixed_start_date',
               'weekly_start_date', 'pattern_start_date'];
    var out = {};
    ids.forEach(function(id) {
        var el = document.getElementById(id);
        out[id] = el ? el.value : '(missing)';
    });
    el = document.getElementById('import_start_date');
    out['import_start_date'] = el ? el.value : '(missing)';
    return out;
}''')
check('AC-7 Upload Directory & Start Date metode tetap kosong',
      all(empties[k] == '' for k in empties if k != 'import_start_date'),
      empties)

# #import_start_date hanya boleh berisi default wartawan (tanggal besok),
# bukan nilai dari file settings.
tomorrow = page.evaluate('''() => {
    var d = new Date();
    d.setDate(d.getDate() + 1);
    return d.toISOString().split('T')[0];
}''')
check('AC-7 #import_start_date tidak diisi dari file settings',
      empties['import_start_date'] == tomorrow,
      (empties['import_start_date'], tomorrow))

# File settings yang di-save TIDAK boleh mengandung upload_directory /
# start_date sama sekali.
saved_payload = page.evaluate('''() => {
    var captured = null;
    window.__origCreate = URL.createObjectURL;
    URL.createObjectURL = function(blob) {
        captured = blob;
        return 'blob:stub';
    };
    var origClick = HTMLAnchorElement.prototype.click;
    HTMLAnchorElement.prototype.click = function() { window.__lastDownloadName = this.download; };
    saveFixedSettings();
    URL.createObjectURL = window.__origCreate;
    HTMLAnchorElement.prototype.click = origClick;
    return {name: window.__lastDownloadName};
}''')
check('AC-7 Save tetap memakai satu format file (upload_schedule_settings_*.json)',
      saved_payload['name'] == 'upload_schedule_settings_fixed.json',
      saved_payload)

